A tabu search on the sum of fourth powers of the sidelobes, with restarts, returning the best code by (PSL, ISL).

```python
import random, time

def construct():
    n, rng, deadline = 64, random.Random(1), time.monotonic() + 20
    def corr(s):
        return [sum(s[j] * s[j + k] for j in range(n - k)) for k in range(1, n)]
    def key(c):
        return (max(map(abs, c)), sum(x * x for x in c))
    best = [rng.choice((1, -1)) for _ in range(n)]
    best_key = key(corr(best))
    while time.monotonic() < deadline:
        s = [rng.choice((1, -1)) for _ in range(n)]
        c = [0] + corr(s)
        tabu, step = [0] * n, 0
        for step in range(1, 40 * n):
            if time.monotonic() > deadline:
                break
            moves = []
            for i in range(n):
                if tabu[i] > step:
                    continue
                e = 0
                for k in range(1, n):
                    v = c[k] - 2 * s[i] * ((s[i + k] if i + k < n else 0) + (s[i - k] if i >= k else 0))
                    e += v ** 4
                moves.append((e, i))
            _, i = min(moves)
            for k in range(1, n):
                c[k] -= 2 * s[i] * ((s[i + k] if i + k < n else 0) + (s[i - k] if i >= k else 0))
            s[i] = -s[i]
            tabu[i] = step + rng.randint(4, 12)
            if key(c[1:]) < best_key:
                best, best_key = list(s), key(c[1:])
    return best
